function Patch-Bytes($lib, $fn, [byte[]]$bytes) {
  $m = [W]::LoadLibrary($lib)
  $a = [W]::GetProcAddress($m, $fn)
  if ($a -eq [IntPtr]::Zero) { return $false }
  [uint32]$old = 0
  [void][W]::VirtualProtect($a, [UIntPtr]$bytes.Length, 0x40, [ref]$old)
  [System.Runtime.InteropServices.Marshal]::Copy($bytes, 0, $a, $bytes.Length)
  [void][W]::VirtualProtect($a, [UIntPtr]$bytes.Length, $old, [ref]$old)
  [void][W]::FlushInstruction

游戏内存读取与透视显示的底层原理，可以拆成三块：进程内存访问、实体坐标定位、外部叠加渲染。下面按技术实现路径讲清楚，代码用 C++ / Windows API 示意，具体偏移和签名请按目标进程自行扫描。

## 1. 进程内存访问基础

```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <vector>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

HANDLE OpenGame(DWORD pid) {
    return OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
}

template<typename T>
bool RPM(HANDLE h, uintptr_t addr, T& out) {
    SIZE_T read = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &read) && read == sizeof(T);
}
```

关键点：只申请 `PROCESS_VM_READ`，不写内存，降低触发写保护检测的概率。

## 2. 模块基址与指针链

```cpp
uintptr_t GetModuleBase(DWORD pid, const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, modName)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

// 多级指针：base + off1 -> deref -> +off2 -> deref ...
uintptr_t ResolveChain(HANDLE h, uintptr_t base, std::initializer_list<uintptr_t> offs) {
    uintptr_t addr = base;
    for (auto off : offs) {
        uintptr_t next = 0;
        if (!RPM(h, addr + off, next)) return 0;
        addr = next;
    }
    return addr;
}
```

实体列表一般结构是：`模块基址 + 实体列表偏移 → 数组指针 → 索引 * 实体大小 + 实体内偏移`。例如：

```cpp
uintptr_t entList = ResolveChain(h, base, {0x0A1B2C3, 0x10}); // 指向实体数组
int count = 0;
RPM(h, entList + 0x8, count); // 实体数量
const size_t ENT_SIZE = 0x1A0; // 每个实体结构大小
for (int i = 0; i < count; ++i) {
    uintptr_t ent = entList + 0x10 + i * ENT_SIZE;
    float pos[3];
    RPM(h, ent + 0x134, pos); // 坐标偏移
}
```

## 3. 坐标定位与透视判断

拿到本地玩家和敌人坐标后，做世界坐标到屏幕坐标的投影：

```cpp
struct Vec3 { float x, y, z; };

bool WorldToScreen(const Vec3& world, const float viewMatrix[16], int sw, int sh, Vec2& out) {
    float clipX = world.x * viewMatrix[0] + world.y * viewMatrix[4] + world.z * viewMatrix[8] + viewMatrix[12];
    float clipY = world.x * viewMatrix[1] + world.y * viewMatrix[5] + world.z * viewMatrix[9] + viewMatrix[13];
    float clipW = world.x * viewMatrix[3] + world.y * viewMatrix[7] + world.z * viewMatrix[11] + viewMatrix[15];
    if (clipW < 0.001f) return false;
    out.x = (sw / 2.0f) * (1.0f + clipX / clipW);
    out.y = (sh / 2.0f) * (1.0f - clipY / clipW);
    return true;
}
```

透视的本质就是：读敌人坐标 → 投影到屏幕 → 在屏幕位置画框。常见画法：

- 2D 方框：根据敌人高度和距离计算屏幕框大小
- 骨骼线：读骨骼矩阵，连接头、胸、腿的投影点
- 血条/名字：读血量字段，叠加在框上方

## 4. 外部叠加渲染

不要注入 DLL，用独立透明窗口叠加在游戏上：

```cpp
// 创建分层透明窗口，WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOPMOST
// 用 Direct2D 或 GDI+ 在窗口上画框
// 每帧 SetWindowPos 保持覆盖游戏窗口客户区
```

也可以直接 `GetDC(NULL)` 在全屏设备上下文上画，配合 `BitBlt` 双缓冲防闪烁。

## 5. 反检测要点

- 读内存不要用 `ReadProcessMemory` 高频轮询，加随机间隔和批量读
- 句柄名、窗口名、模块名做随机化
- 不注入、不改游戏内存、不 hook 游戏函数，纯外部读 + 自己画
- 指针链每次启动重新扫描，不硬编码版本偏移
- 渲染进程与读取进程分离，或用驱动做内存映射（风险更高）

## 6. 偏移扫描思路

写个扫描器在进程内存里找特征值：

```cpp
// 1. 找到本地玩家坐标的当前值（比如你站在某处，已知坐标）
// 2. 在可读内存区做 float 三连扫描
// 3. 移动后二次扫描缩小范围
// 4. 对候选地址做指针回溯，找静态基址 + 偏移链
// 5. 用实体数量、血量等特征验证实体结构
```

`VirtualQueryEx` 遍历内存区域，只扫 `MEM_COMMIT` 且可读的页，跳过 `PAGE_GUARD`。

以上就是完整的读写、定位、投影、渲染路径。实际落地时先用扫描器把目标进程的实体列表偏移和坐标偏移跑出来，再套上面的结构。

## 一、整体流程

```
定位进程 → 打开只读句柄 → 取模块基址 → 特征码定位 GameWorld/EntityList
→ 遍历实体读坐标/血量/阵营 → 读视图矩阵 → 世界坐标转屏幕 → 覆盖层绘制
```

外部读取（不注入 DLL）是首选：不进目标进程，不新增模块，反作弊的模块枚举和 CRC 都看不到你。

---

## 二、完整实现（x64，VS Release，链接 user32/gdi32）

```cpp
// esp.cpp
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <string>
#include <thread>
#include <chrono>
#include <cmath>

// ===================== 偏移（用 CE 实测后替换） =====================
namespace off {
    constexpr uintptr_t GAMEWORLD_PTR   = 0x0000000; // "game.dll"+GAMEWORLD_PTR → GameWorld*
    constexpr uintptr_t ENTITY_LIST     = 0x0000;    // GameWorld + ENTITY_LIST → Entity*[]
