class Mem {
public:
    HANDLE h = nullptr;
    DWORD  pid = 0;
    uintptr_t base = 0;
    size_t    size = 0;

    // 只给 VM_READ：写入权限一律不要，能显著降低行为分
    bool Attach(const wchar_t* proc, const wchar_t* mod) {
        pid = GetPidByName(proc);
        if (!pid) return false;
        h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
        if (!h) return false;
        ModInfo mi = GetModuleInfo(pid, mod);
        base = mi.base; size = mi.size;
        return base != 0;
    }

    bool ReadRaw(uintptr_t addr, void* buf, size_t n) const {
        if (!h || !addr) return false;
        SIZE_T read = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, buf, n, &read) && read == n;
    }

    template <typename T>
    T Read(uintptr_t addr) const {
        T v{};
        ReadRaw(addr, &v, sizeof(T));
        return v;
    }

    // 一次读整块，减少 ReadProcessMemory 调用次数（降低检测面）
    template <typename T>
    bool ReadBlock(uintptr_t addr, T& out) const {
        return ReadRaw(addr, &out, sizeof(T));
    }

    uintptr_t ReadPtr(uintptr_t addr) const { return Read<uintptr_t>(addr); }

    // ReadChain(base, {off1, off2, off3}) → 最终地址处的值
    template <typename T>
    T ReadChain(uintptr_t addr, std::initializer_list<uintptr_t> offs) const {
        uintptr_t p = addr;
        for (uintptr_t o : offs) {
            p = ReadPtr(p + o);
            if (!p || p < 0x10000) return T{};
        }
        return Read<T>(p);
    }
};

